<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<title>DSWD MIMAROPA Queue Kiosk</title>
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<style>
*{box-sizing:border-box}body{margin:0;font-family:Arial,sans-serif;background:#eef3f8;color:#111827}.wrap{max-width:980px;margin:0 auto;padding:24px}.card{background:white;border-radius:22px;padding:24px;box-shadow:0 14px 40px rgba(15,23,42,.18)}h1{text-align:center;color:#00008b;margin:0 0 8px}.note{text-align:center;color:#475569}.section{background:#f8fafc;border:1px solid #d6dce8;border-radius:16px;padding:16px;margin-top:14px}.section h2{margin:0 0 12px;font-size:18px;color:#0f2f56}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:12px}.field{display:flex;flex-direction:column}.field label{font-size:13px;font-weight:bold;margin-bottom:5px}.field input,.field select{height:44px;border:1px solid #cbd5e1;border-radius:9px;padding:0 10px;font-size:15px}.two{grid-column:span 2}.buttons{display:flex;flex-direction:column;gap:12px}.assist{height:72px;border-radius:999px;border:4px solid #08b7e5;background:linear-gradient(#f8fbfb,#dde4e6);box-shadow:5px 7px 0 rgba(0,0,0,.22);font-size:23px;font-weight:900;text-align:left;padding-left:42px;cursor:pointer}.assist:hover{background:#eef9ff}.status{text-align:center;font-weight:900;min-height:26px;margin-top:12px;color:#0f766e}.err{color:#dc2626}.result{display:none;text-align:center;background:#eff6ff;border:1px solid #bfdbfe;border-radius:16px;padding:18px;margin-top:14px}.queue{font-size:54px;font-weight:1000;color:#00008b}.btn{border:0;border-radius:999px;padding:13px 22px;font-weight:900;cursor:pointer;margin:5px}.print{background:#16a34a;color:white}.again{background:#0b2e83;color:white}.stubwrap{display:none}.stub{width:80mm;max-width:80mm;margin:0 auto;padding:8mm 6mm;background:#fff;color:#111}.stub h2{text-align:center;margin:0 0 6px}.row{display:flex;justify-content:space-between;border-bottom:1px dotted #aaa;font-size:12px;padding:5px 0;gap:10px}.row b{text-align:right}@media(max-width:760px){.grid{grid-template-columns:1fr}.two{grid-column:span 1}.assist{font-size:18px}}@media print{.wrap{display:none}.stubwrap{display:block}@page{size:80mm auto;margin:0}}
</style>
</head>
<body>
<div class="wrap"><div class="card"><h1>DSWD MIMAROPA Registration Kiosk</h1><p class="note">Fill in beneficiary details and complete MIMAROPA address, then tap the assistance type.</p>
<div class="section"><h2>Beneficiary Information</h2><div class="grid"><div class="field"><label>First Name *</label><input id="firstName"></div><div class="field"><label>Middle Name</label><input id="middleName"></div><div class="field"><label>Last Name *</label><input id="lastName"></div><div class="field"><label>Ext. Name</label><input id="extName"></div><div class="field two"><label>Contact Number *</label><input id="contactNumber" placeholder="09XXXXXXXXX or +639XXXXXXXXX"></div><div class="field two"><label>Region</label><input value="MIMAROPA" readonly></div></div></div>
<div class="section"><h2>Complete Address - MIMAROPA Only</h2><div class="grid"><div class="field"><label>Province / Location *</label><select id="province"><option value="">Select</option><option>Oriental Mindoro</option><option>Occidental Mindoro</option><option>Marinduque</option><option>Romblon</option><option>Palawan</option><option>Puerto Princesa City</option></select></div><div class="field"><label>City / Municipality *</label><input id="city"></div><div class="field"><label>Barangay *</label><input id="barangay"></div><div class="field"><label>House No. / Street / Sitio *</label><input id="street"></div></div></div>
<div class="section"><h2>Select Assistance Type</h2><div class="buttons"><button class="assist" onclick="generateQueue('Medical Assistance')">Medical Assistance</button><button class="assist" onclick="generateQueue('Funeral Assistance')">Funeral Assistance</button><button class="assist" onclick="generateQueue('Educational Assistance')">Educational Assistance</button><button class="assist" onclick="generateQueue('Transportation Assistance')">Transportation Assistance</button><button class="assist" onclick="generateQueue('Material Assistance')">Material Assistance</button><button class="assist" onclick="generateQueue('Food Assistance')">Food Assistance</button><button class="assist" onclick="generateQueue('Cash Relief Assistance')">Cash Relief Assistance</button></div><div id="status" class="status"></div></div>
<div id="result" class="result"><h2>Queue Generated</h2><div id="queueNo" class="queue">-</div><p id="summary"></p><button class="btn print" onclick="printStub()">Print Stub</button><button class="btn again" onclick="resetScreen()">New Queue</button></div></div></div>
<div class="stubwrap"><div class="stub"><h2>DSWD QUEUE STUB</h2><div class="row"><span>Queue Number</span><b id="stubQueue">-</b></div><div class="row"><span>Beneficiary Code</span><b id="stubCode">-</b></div><div class="row"><span>Name</span><b id="stubName">-</b></div><div class="row"><span>Contact</span><b id="stubContact">-</b></div><div class="row"><span>Assistance</span><b id="stubProgram">-</b></div><div class="row"><span>Address</span><b id="stubAddress">-</b></div><div class="row"><span>Date / Time</span><b id="stubDate">-</b></div><p style="font-size:11px;text-align:center">Please keep this stub and wait for your number to be called.</p></div></div>
<script>
let lastQueue=null;function v(id){return document.getElementById(id).value.trim()}function okPhone(x){return /^09\d{9}$/.test(x)||/^\+639\d{9}$/.test(x)||/^639\d{9}$/.test(x)}function validate(){if(!v('firstName')||!v('lastName'))return'Please enter first name and last name.';if(!okPhone(v('contactNumber')))return'Please enter a valid contact number.';if(!v('province')||!v('city')||!v('barangay')||!v('street'))return'Please complete the MIMAROPA address.';return''}async function generateQueue(program){const status=document.getElementById('status');status.className='status';const err=validate();if(err){status.className='status err';status.textContent=err;return}status.textContent='Generating queue...';try{const body={first_name:v('firstName'),middle_name:v('middleName'),last_name:v('lastName'),ext_name:v('extName'),contact_number:v('contactNumber'),province:v('province'),city_municipality:v('city'),barangay:v('barangay'),street_address:v('street'),program_type:program};const res=await fetch('../api/kiosk_generate_queue.php',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});const data=await res.json();if(!data.success)throw new Error(data.message||'Unable to generate queue.');lastQueue=data;document.getElementById('queueNo').textContent=data.queue_number;document.getElementById('summary').textContent=data.client_name+' - '+data.program_type+' - MIMAROPA';setStub(data);document.getElementById('result').style.display='block';status.textContent='Queue number ready. You may print the stub.'}catch(e){status.className='status err';status.textContent=e.message}}function setStub(d){stubQueue.textContent=d.queue_number||'-';stubCode.textContent=d.beneficiary_code||'-';stubName.textContent=d.client_name||'-';stubContact.textContent=d.contact_number||'-';stubProgram.textContent=d.program_type||'-';stubAddress.textContent=d.address||'-';stubDate.textContent=d.date_time||new Date().toLocaleString()}function printStub(){if(lastQueue)setStub(lastQueue);setTimeout(()=>window.print(),80)}function resetScreen(){lastQueue=null;result.style.display='none';status.textContent='';['firstName','middleName','lastName','extName','contactNumber','province','city','barangay','street'].forEach(id=>document.getElementById(id).value='')}
</script>
</body>
</html>
